INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(1,'OAKLEY HALFTRACK MID ll BLACK','FOF100334-001','499900.0',3,5,6,1,'/images/1778097912736-descarga.png',0,0,'El Halftrack Mid II en negro total es la expresión más auténtica del ADN militar de Oakley. Su caña media combina tejido técnico, gamuza y materiales sintéticos de alta resistencia para envolver el tobillo con el soporte necesario en el día a día más exigente. La entresuela de espuma de alta densidad amortigua cada pisada con precisión, mientras la suela de goma de alta tracción garantiza un agarre firme en cualquier superficie. Su forro interior acolchado y transpirable mantiene el pie fresco y protegido durante horas. Una zapatilla negra, imponente y construida para durar.','7.5,10','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(2,'OAKLEY FLAK lll GREY/BLACK','FOF100575-213','549900.0',3,5,6,1,'/images/1779220161920-corrige_el_color_de_la_202605191448.jpeg',0,0,'El Flak III en gris y negro es la zapatilla de suela gruesa que redefine la moda urbana de Oakley. Su parte superior de cuero nobuk combinada con lona resistente ofrece una mezcla de durabilidad táctil y transpirabilidad que pocas zapatillas logran. La suela de goma vulcanizada de perfil voluminoso garantiza una tracción excepcional y un desgaste mínimo con el tiempo. La entresuela moldeada absorbe los impactos con comodidad, y los detalles del emblema de Oakley en metal rematan un diseño que combina robustez y estilo en partes iguales. El contraste en gris y negro la convierte en una pieza versátil que acompaña cualquier atuendo.','8.5,11','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(3,'OAKLEY BRIGDE BLACK','FOF100631-001','499900.0',3,5,6,1,'/images/1778098225228-oakley-brigde-black.jpg_202605061510.jpeg',0,0,'El Bridge en negro es la apuesta minimalista y elegante de Oakley para el día a día urbano. Construida con cuero sintético de alta calidad, su superficie lisa y uniforme transmite sobriedad y carácter en cada detalle. La suela de goma antideslizante proporciona estabilidad en cualquier terreno, mientras la plantilla acolchada se adapta a la forma del pie para una comodidad sostenida durante todo el día. Su silueta baja y completamente negra hace del emblema de Oakley el único y poderoso protagonista. Una zapatilla limpia, duradera y pensada para quienes eligen el estilo sin complicaciones.','11','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(4,'OAKLEY ANORAK LOW BLACK','FOF100614-001','649900.0',3,5,6,1,'/images/1778098315525-oakley-anorak-low-black.jpg_202605061511.jpeg',0,0,'La Anorak Low en negro es el punto de encuentro entre el mundo outdoor y el estilo urbano de Oakley. Su parte superior de gamuza de alta calidad en tono negro proyecta un acabado robusto y elegante que resiste el uso intenso del día a día. La entresuela de espuma de alta densidad amortigua con precisión cada impacto, mientras la suela de goma de alta resistencia garantiza tracción firme en cualquier superficie. El emblema de Oakley en metal remata un diseño sólido, pensado para quienes combinan movimiento y estilo sin concesiones.','7','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(5,'BOTA OAKLEY HALFTRACK MID ll BLACK/GUM','FOF100334-053','535900.0',3,5,6,1,'/images/1778891562692-genera_una_imagen_de_este_202605151932.jpeg',0,0,'La Halftrack Mid II en negro con detalle de goma natural es la bota femenina de Oakley que no pide permiso. Su caña media combina tejido técnico, gamuza y materiales sintéticos de alta resistencia para brindar soporte total al tobillo en cada jornada. La entresuela de espuma de alta densidad amortigua cada pisada con precisión, y la suela de goma en tono natural aporta un contraste que distingue esta versión del resto de la línea. El forro interior acolchado y transpirable mantiene el pie fresco y protegido. Una bota con carácter propio.','7.5','2026-04-22 07:24:52','/videos/1778971510341-FOF100334-053-video.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(6,'OAKLEY HALFTRACK LOW lll NEW KHAKI','FOF100670-323','629900.0',3,5,6,1,'/images/1778099494419-oakley-halftrack-low-lll-new-khaki.jpg_202605061530.jpeg',0,0,'La Halftrack III en caqui es la evolución más completa de la icónica familia Halftrack de Oakley. Su parte superior de materiales sintéticos reforzados y tejido transpirable en tono caqui combina durabilidad y frescura para el uso urbano diario. La entresuela de espuma de alta densidad garantiza una amortiguación superior a sus predecesores, mientras la suela de goma de alta tracción ofrece agarre omnidireccional en cualquier superficie. Una zapatilla en verde militar que equilibra rendimiento y estilo a la perfección.','7,10','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(7,'OAKLEY HALFTRACK MID ll NEW KHAKI','FOF100334-323','535900.0',3,5,6,1,'/images/1778795351897-oakley-halftrack-mid-ll-new-khaki.jpg_202605141649.jpeg',0,0,'El Halftrack Mid II en caqui es la versión unisex del icónico modelo de Oakley en su paleta más versátil. Su caña media de tejido técnico, gamuza y materiales sintéticos brinda soporte al tobillo con un tono caqui que combina con cualquier atuendo casual. La entresuela de espuma de alta densidad garantiza amortiguación precisa en cada paso, y la suela de goma robusta con tracción omnidireccional asegura estabilidad en todo momento. El forro interior acolchado y transpirable acompaña el pie durante horas sin sacrificar la comodidad.','7,7.5,10','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(8,'OAKLEY LOW NEW ll KHAKI','FOF100335-323','535900.0',3,5,6,1,'/images/1778099588262-oakley-low-new-ll-khaki.jpg_202605061532.jpeg',0,0,'El Halftrack Low II en caqui es la versión de caña baja del clásico Halftrack de Oakley, diseñada para quienes buscan libertad de movimiento sin renunciar al estilo. Su parte superior de tejido técnico, gamuza y materiales sintéticos en tono caqui ofrece durabilidad y frescura para el día a día. La entresuela de espuma de alta densidad amortigua con precisión, mientras la suela de goma robusta con tracción multidireccional garantiza agarre en cualquier terreno. Una zapatilla versátil en una paleta de color que acompaña todo tipo de conjuntos.','7,10','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(10,'OAKLEY TEETH NOISE JET BLACK','FOF100546-01K','759900.0',3,5,6,1,'/images/1778102751072-oakley-teeth-noise-jet-black.jpg_202605061625.jpeg',0,1,'El Teeth Noise en negro azabache es la zapatilla más audaz de la familia Teeth de Oakley. Su parte superior de gamuza y cuero de alta calidad en tono negro profundo combina sofisticación y carácter en cada detalle. La entresuela reforzada con espuma proporciona amortiguación ligera y estabilidad, mientras la suela de goma adherente con excelente resistencia a la abrasión prolonga la vida útil de la zapatilla. El emblema de Oakley en metal y el tirador trasero rematan un diseño disruptivo pensado para quienes buscan hacer una declaración de estilo única.','10','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(11,'OAKLEY BRIGDE UNIFORM GRAY','FOF100631-25N','599900.0',3,5,6,1,'/images/1778103057129-oakley-brigde-uniform-gray.jpg_202605061630.jpeg',0,0,'El Bridge en gris uniforme es la versión más sofisticada de la silueta minimalista de Oakley. Su cuero sintético de alta calidad en tono gris neutro transmite elegancia discreta y versatilidad para cualquier ocasión. La suela de goma antideslizante proporciona estabilidad en cualquier terreno, mientras la plantilla acolchada se adapta a la forma del pie para una comodidad sostenida durante todo el día. Un gris que acompaña desde el atuendo más formal hasta el más relajado, siempre con el emblema de Oakley como sello distintivo.','10','2026-04-22 07:24:52','/videos/1778971539138-FOF100631-25N-video.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(12,'OAKLEY HALFTRACK ll PREMIUM STONE GRAY','FOF100522-22Y','468900.0',3,5,6,1,'/images/1778103209557-oakley-halftrack-ll-premium-stone-gray.jpg_202605061633.jpeg',0,0,'El Halftrack Low II Premium en gris piedra es la edición más refinada del icónico modelo de Oakley. Su parte superior de cuero y tejido de materiales cuidadosamente seleccionados en tono gris piedra combina durabilidad premium con una estética urbana sofisticada. La entresuela de espuma de alta densidad ofrece amortiguación precisa en cada pisada, mientras la plantilla suave y perforada mejora la transpirabilidad para un confort sostenido durante todo el día. La suela de goma con alta resistencia a la abrasión garantiza durabilidad superior. Para el hombre que exige lo mejor en cada detalle.','10','2026-04-22 07:24:52','/videos/1778971545885-FOF100522-22Y-video.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(13,'OAKLEY TEETH NOISE ALMOND','FOF100546-87B','759900.0',3,5,6,1,'/images/1778103237455-oakley-teeth-noise-almond.jpg_202605061633.jpeg',0,1,'El Teeth Noise en tono almendra es la interpretación más cálida y sofisticada de la familia Teeth de Oakley. Su parte superior de gamuza y cuero de primera calidad en color almendra brinda una textura rica y un acabado elegante que lo diferencia del resto de la línea. La entresuela reforzada con espuma proporciona amortiguación ligera y estabilidad, y la suela de goma de alta adherencia garantiza agarre duradero en cualquier superficie. El emblema en metal y el tirador trasero completan un diseño único que combina calidez y audacia.','10','2026-04-22 07:24:52','/videos/1778971551475-FOF100546-87B-video.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(14,'OAKLEY GRANADE BLACK/GUM','FOF100576-053','599900.0',3,5,6,1,'/images/1778103291049-oakley-granade-black_gum.jpg_202605061634.jpeg',0,0,'El Granadier en negro con suela de goma natural es la expresión más táctica del calzado urbano de Oakley. Su parte superior de gamuza y lona resistente en color negro sólido contrasta con la suela de goma natural para crear una combinación que transmite carácter y autenticidad. La entresuela de EVA moldeado absorbe los impactos con comodidad, y la suela de goma vulcanizada de alta tracción garantiza agarre firme y una resistencia excepcional al desgaste. El emblema de Oakley en metal remata una zapatilla robusta, urbana y con ADN militar inconfundible.','9.5,10','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(15,'OAKLEY TEETH 1 GRAY','FOF100545-207','715900.0',3,5,6,1,'/images/1778102594932-oakley-teeth-1-gray.jpg_202605061622.jpeg',0,0,'El Teeth 1 en gris es la edición limitada que rinde homenaje al modelo original que inició la legendaria saga Teeth de Oakley. Construido con poliéster de alta calidad y materiales sintéticos reforzados, ofrece una durabilidad sobresaliente que honra a la pieza que marcó tendencia. Su suela dentada icónica en gris garantiza máximo agarre y una resistencia al desgaste que muy pocas zapatillas logran. Una pieza de colección con rendimiento real, para quienes valoran la historia del diseño urbano.','12','2026-04-22 07:24:52','/videos/1778971556308-FOF100545-207__1_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(16,'OAKLEY FLAK 365 ll LITE NEW KHAKI','FOF100634-323','699900.0',3,5,6,1,'/images/1778099879027-oakley-flak-365-ll-lite-new-khaki.jpg_202605061537.jpeg',0,1,'El Flak 365 II Lite en caqui es la versión más ágil de la línea Flak de Oakley, pensada para el uso diario más exigente. Su parte superior de cuero nobuk y tejido transpirable en tono caqui combina durabilidad táctil con ventilación eficaz para el máximo confort. La plantilla perforada mejora la transpirabilidad de manera constante, mientras la entresuela de EVA moldeado amortigua con ligereza cada pisada. La suela de goma vulcanizada garantiza tracción excepcional y resistencia prolongada al desgaste. Robusta pero ágil, en una paleta de color que combina con todo.','9.5,11','2026-04-22 07:24:52','/videos/1778971562998-FOF100634-323__1_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(17,'OAKLEY TEETH BOMB JET BLACK','FOF100547-01K','749900.0',3,5,6,1,'/images/1778103520400-oakley-teeth-bomb-jet-black.jpg_202605061638.jpeg',0,0,'El Teeth Bomb en negro azabache es la versión más explosiva y voluminosa de la familia Teeth de Oakley. Su parte superior de gamuza de alta calidad en tono negro profundo brinda un acabado táctil premium que resiste el paso del tiempo. La suela de goma de gran volumen con el característico diseño dentado proyecta una presencia imponente y garantiza tracción superior en cualquier superficie. El forro acolchado, la puntera reforzada y el emblema en metal completan una zapatilla que no pasa desapercibida.','10','2026-04-22 07:24:52','/videos/1779639290143-Genera_video_Oakley_Teeth_Bomb_202605241114.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(18,'OAKLEY ANORAK CEMENT 7','FOF100614-314','649900.0',3,5,6,1,'/images/1778103610388-oakley-anorak-cement-7.jpg_202605061640.jpeg',0,0,'La Anorak Low en cemento es la interpretación urbana masculina del calzado outdoor de Oakley. Su parte superior de gamuza de alta calidad en tono cemento grisáceo transmite solidez y un carácter aventurero muy particular. La entresuela de espuma de alta densidad absorbe cada impacto con precisión, y la suela de goma de alta resistencia garantiza tracción firme en cualquier terreno. El emblema de Oakley en metal es el toque final que distingue este modelo como una pieza de calzado urbano con identidad propia.','9.5','2026-04-22 07:24:52','/videos/1778971576227-FOF100614-314__1_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(19,'OAKLEY HALFTRACK LOW II','FOF100469-882','629900.0',3,5,6,1,'/images/1778103717283-oakley-halftrack-low-ii.jpg_202605061641.jpeg',0,0,'El Halftrack Low II en colorway especial para hombre es la versión de caña baja del clásico Halftrack de Oakley en una edición diferenciada. Su parte superior de cuero y tejido técnico de alta calidad combina durabilidad y un diseño distintivo para el uso urbano diario. La plantilla suave y perforada garantiza transpirabilidad constante, y la entresuela de espuma de alta densidad amortigua cada pisada con precisión. La suela de goma de alta resistencia a la abrasión garantiza tracción firme y durabilidad superior. Para el hombre que busca diferenciarse en cada paso.','9.5','2026-04-22 07:24:52','/videos/1778971585017-FOF100469-882__1_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(20,'ADIDAS RESPONSE RUNNER','JQ2540','299900.0',2,5,6,2,'/images/1778103760374-adidas-response-runner.jpg_202605061642.jpeg',1,0,'La Response Runner de Adidas es la zapatilla de entrenamiento femenina que combina comodidad y versatilidad para el día a día activo. Su parte superior de malla gruesa fabricada con al menos el 50% de materiales reciclados garantiza durabilidad y una gestión eficiente de la humedad durante el uso. La entresuela de espuma EVA ofrece amortiguación ligera y confiable en cada paso, mientras la suela de gran agarre mantiene la estabilidad en superficies variadas. La puntera protectora y el refuerzo en el talón aportan soporte adicional para las rutinas más exigentes.','5,5.5,6.5,7','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(21,'ADIDAS GALAXY 7 BLACK','ID8764','339900.0',2,5,6,1,'/images/1778103852244-adidas-galaxy-7-black.jpg_202605061644.jpeg',0,0,'La Galaxy 7 en negro de Adidas es la zapatilla de running femenina diseñada para corredoras que buscan comodidad desde el primer kilómetro hasta el último. Su parte superior de malla exterior ligera y resistente en color negro ofrece excelente gestión de la humedad y una sujeción firme en cada zancada. La entresuela con amortiguación Cloudfoam proporciona una pisada suave y reactiva, ideal para entrenamientos diarios o rutinas de iniciación al running. La suela de material compuesto garantiza durabilidad superior y agarre estable en cualquier superficie.','5.5,7,7.5,8.5','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(22,'ADIDAS RUNNING DURAMO SL 2 BLACK/WHITE-DAMA','IH8225','359900.0',2,5,6,2,'/images/1778190362280-Gemini_Generated_Image_8lmo188lmo188lmo.png',0,1,'La Duramo SL 2 en negro y blanco para mujer de Adidas es la zapatilla de running pensada para la mujer activa que no hace concesiones. Su parte superior de malla técnica y sintética fabricada con al menos el 50% de materiales reciclados ofrece ligereza, transpirabilidad y un ajuste suave al pie. El talón acolchado brinda soporte y comodidad desde el primer paso, mientras la entresuela LIGHTMOTION proporciona amortiguación ligera y estable que acompaña en cada kilómetro. La suela Adiwear garantiza una durabilidad excepcional frente al desgaste diario.','6,7,7.5','2026-04-22 07:24:52','/videos/1778971600698-IH8225.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(23,'ADIDAS RUNNING DURAMO SL 2 BLACK/WHITE','ID8742','499900.0',2,5,6,2,'/images/1778104302664-adidas-running-duramo-sl-2-black_white__1_.jpg_202605061651.jpeg',0,0,'La Duramo SL 2 en negro y blanco de Adidas es la zapatilla de running que combina el clásico contraste bicolor con amortiguación de alta respuesta para el rendimiento diario. Su parte superior de malla técnica fabricada con materiales reciclados garantiza ligereza y transpirabilidad sostenida durante el entrenamiento. La entresuela LIGHTMOTION proporciona amortiguación ligera y estable que protege la articulación en cada pisada, mientras la suela Adiwear resiste el desgaste del día a día con una durabilidad sobresaliente.','5.5,7,7.5','2026-04-22 07:24:52','/videos/1778971606008-ID8742__1_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(24,'ADIDAS DURAMO RC2','JR7151','319900.0',2,1,2,1,'/images/1778104364297-adidas-duramo-rc2.jpg_202605061652.jpeg',0,0,'La Duramo RC2 de Adidas es la zapatilla de running inspirada en el mundo de la competencia, creada para el corredor que busca velocidad y comodidad en cada entrenamiento. Su parte superior de malla transpirable permite un flujo de aire constante que mantiene el pie fresco durante las sesiones más largas. La entresuela LIGHTMOTION garantiza una amortiguación ligera y reactiva en cada zancada, y la suela Adiwear ofrece una resistencia al desgaste excepcional para quienes suman kilómetros cada día. Ligereza extrema sin sacrificar el rendimiento.','8,10,11','2026-04-22 07:24:52','/videos/1779170718044-Adidas_Duramo_RC2_video_generation_202605190102__online-video-cutter.com_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(25,'ADIDAS TERREX TRACEFINDER 2','JR9142','399900.0',2,1,2,2,'/images/1778104527647-adidas-terrex-tracefinder-2.jpg_202605061653.jpeg',0,0,'La Terrex Tracefinder 2 de Adidas es la zapatilla de trail running diseñada para conquistar terrenos variados con confianza. Su parte superior de malla técnica ligera y transpirable con refuerzos cosidos protege el pie en los senderos más exigentes, mientras la punta reforzada defiende de rocas y escombros en el camino. La entresuela de espuma EVA proporciona amortiguación duradera y ligera, y la suela TRAXION de tacos multidireccionales garantiza agarre óptimo incluso en terrenos húmedos y resbaladizos. Fabricada con al menos el 20% de material reciclado.','6,7,7.5,8','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(26,'ADIDAS RESPONSE RUNNER 2','KJ1735','299900.0',2,5,6,1,'/images/1778104644221-adidas-response-runner-2__1_.jpg_202605061657.jpeg',1,0,'La Response Runner 2 de Adidas para hombre es la segunda generación de uno de los modelos de running diario más populares de la marca. Su parte superior de malla gruesa y transpirable, reforzada en puntera y talón, ofrece sujeción firme y durabilidad mejorada para entrenamientos frecuentes. La mediasuela de espuma EVA proporciona amortiguación confiable en cada zancada, y la suela de alta tracción garantiza estabilidad en superficies de asfalto o gimnasio. Un modelo actualizado que mantiene la comodidad de siempre con mejoras precisas para el corredor masculino activo.','9,9.5,10,11','2026-04-22 07:24:52','/videos/1778824391453-Tenis_varias_perspectivas_transi__202605150052.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(27,'ADIDAS RUNNING RUNFALCON 5 TR SHADOW','JQ6958','399900.0',2,5,6,1,'/images/1778104680813-adidas-running-runfalcon-5-tr-shadow.jpg_202605061653.jpeg',0,1,'La Runfalcon 5 TR en verde sombra de Adidas es la zapatilla de sendero ligero diseñada para terrenos mixtos con estilo propio. Su parte superior de malla con resistencia al agua y detalles reflectantes protege el pie en condiciones húmedas mientras mantiene la ventilación activa. La mediasuela Cloudfoam proporciona amortiguación confiable paso a paso, y la suela Adiwear con tracción reforzada ofrece agarre seguro en asfalto, gravilla o tierra compacta. El tono verde sombra combina con el entorno natural y la actitud de quienes entrenan sin límites.','8,9,9.5,10','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(28,'ADIDAS DURAMO RC2','JS4435','299900.0',2,5,6,2,'/images/1778104726570-adidas-duramo-rc2__1_.jpg_202605061653.jpeg',0,0,'La Duramo RC2 de Adidas en su versión unisex es la zapatilla de running de alta respuesta que se adapta a cualquier tipo de corredor. Su parte superior de malla textil transpirable con al menos un 50% de materiales reciclados garantiza un ajuste cómodo y una gestión eficaz del calor interior. La espuma de la mediasuela ofrece amortiguación ligera y reactiva que acompaña cada zancada con energía, mientras la suela Adiwear entrega durabilidad y agarre superiores en el asfalto. Un diseño neutro y funcional para el entrenamiento diario sin importar el género.','6,6.5,7,8','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(29,'ADIDAS RESPONSE RUNNER 2','KJ1738','299900.0',2,5,6,2,'/images/1778104765268-adidas-response-runner-2.jpg_202605061659.jpeg',0,0,'La Response Runner 2 de Adidas para mujer combina comodidad estructurada y estilo deportivo en un modelo pensado para el día a día activo. Su parte superior de malla transpirable con soporte medial reforzado envuelve el pie con sujeción firme y ventilación constante a lo largo de cada sesión. La mediasuela de espuma EVA amortigua el impacto de cada paso con eficiencia, y la suela de alta tracción asegura estabilidad en cualquier superficie. Diseñada para la corredora que no se detiene, ya sea en la pista o en la calle.','4,4.5,6','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(30,'ADIDAS RUNNING RUNFALCON 5 TR-CORE BLACK/SILVER','JP5911','399900.0',2,NULL,NULL,2,'/images/1778104842645-adidas-running-runfalcon-5-tr-core-black_silver.jpg_202605061700__1_.jpeg',0,0,'La Runfalcon 5 TR en negro y plata de Adidas es la zapatilla de sendero ligero que combina resistencia técnica con un perfil deportivo y limpio. Su parte superior de malla con resistencia al agua y detalles reflectantes plateados protege el pie en condiciones variables mientras maximiza la visibilidad en entrenamientos de poca luz. La mediasuela Cloudfoam ofrece amortiguación confiable y reactiva, y la suela Adiwear con tracción reforzada garantiza agarre firme en superficies mixtas. Negro y plata: funcionalidad y estilo sin concesiones.','6,6.5,7','2026-04-22 07:24:52','/videos/1778971635369-JP5911__1_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(31,'ADIDAS SWITCH MOVE','ID8329','299900.0',2,5,6,2,'/images/1778109420570-adidas-switch-move.jpg_202605061816.jpeg',0,0,'La Switch Move de Adidas es la zapatilla de entrenamiento cruzado que acompaña cada transición del día sin esfuerzo. Su parte superior de malla exterior ligera, fabricada con al menos un 50% de materiales reciclados, ofrece ventilación activa y un ajuste cómodo adaptado a múltiples movimientos. La mediasuela de espuma EVA ligera amortigua cada pisada con eficiencia, y la suela Adiwear de alta durabilidad y tracción lateral garantiza estabilidad en clases de entrenamiento funcional o en el uso cotidiano. Una zapatilla ágil y versátil para quienes nunca se quedan quietos.','4,6.5,7','2026-04-22 07:24:52','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(32,'ADIDAS RUNVISTA','HQ2329','299900.0',2,5,6,2,'/images/1778109768392-adidas-runvista.jpg_202605061822.jpeg',0,0,'La Runvista de Adidas es el puente perfecto entre el estilo retro de entrenamiento y la comodidad actual. Su parte superior combina cuero sintético con malla técnica transpirable para lograr un aspecto clásico y limpio que no pierde vigencia. La mediasuela de espuma EVA inyectada absorbe los impactos con suavidad y ofrece una pisada reactiva para el uso diario, mientras la suela de goma de alta tracción asegura agarre en cualquier superficie. Una zapatilla de perfil deportivo-casual en blanco que combina con prácticamente todo.','6.5,7,7.5,8','2026-04-22 07:24:52','','ORIGINAL',NULL);
