INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(45,'ADIDAS RESPONSE RUNNER 2','KJ1736','299900.0',2,NULL,NULL,4,'/images/1778110970467-adidas-response-runner-2.jpg_202605061842.jpeg',0,0,'La Response Runner 2 de Adidas es la zapatilla de entrenamiento cotidiano que ofrece comodidad de calidad en cada paso. Su parte superior de malla gruesa y transpirable, con refuerzo en puntera y talón, garantiza sujeción firme y durabilidad mejorada frente a la primera generación. La mediasuela de espuma EVA proporciona amortiguación confiable y liviana, y la suela de alta tracción mantiene la estabilidad en asfalto o gimnasio durante horas de uso continuo. Una zapatilla versátil y actualizada para el deportista que pide más de su calzado sin pagar de más.','8,8.5,9,10.5','2026-04-23 00:39:32','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(46,'ADIDAS RESPONSE RUNNER 2','KJ1745','299900.0',2,NULL,NULL,4,'/images/1778111005648-adidas-response-runner-2__1_.jpg_202605061843.jpeg',0,0,'La Response Runner 2 de Adidas combina ingeniería de confort con un diseño depurado para el running de todos los días. Su parte superior de malla técnica y transpirable, reforzada en las zonas de mayor desgaste, ofrece soporte estructurado y ventilación constante durante el entrenamiento. La mediasuela de espuma EVA amortigua cada zancada con precisión, y la suela de alta tracción asegura agarre firme y durabilidad en superficies de asfalto. Un modelo confiable, cómodo y listo para cubrir todos los kilómetros del día.','7,8,9,9.5,10','2026-04-23 00:41:35','/videos/1778973370109-Adidas_tennis_showcase_video_202605161815.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(47,'ADIDAS RESPONSE RUNNER','IH6103','299900.0',2,NULL,NULL,4,'/images/1778853543971-Fondo_blanco_y_un_par_202605150858.jpeg',0,0,'La Response Runner de Adidas en tono azul es la zapatilla de entrenamiento diario que combina funcionalidad confiable con un colorway fresco y deportivo. Su parte superior de malla gruesa y transpirable, elaborada con al menos un 50% de materiales reciclados, gestiona activamente el calor interior mientras ofrece una sujeción cómoda y adaptable al pie. La mediasuela de espuma EVA amortigua cada paso con eficiencia, y la suela de alta tracción garantiza estabilidad firme en cualquier superficie. Un modelo versátil que acompaña tanto el entrenamiento como el día casual con solidez y comodidad.','8,9,9.5','2026-04-23 00:43:54','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(48,'ADIDAS RESPONSE SUPER','JQ2524','399900.0',2,NULL,NULL,1,'/images/1778111841605-adidas-response-super.jpg_202605061857.jpeg',0,0,'La Response Super de Adidas es la zapatilla de running de alto rendimiento diseñada para el corredor que exige más en cada salida. Su parte superior de monomalla transpirable mantiene el pie fresco y bien contenido durante sesiones exigentes, mientras la plantilla OrthoLite proporciona soporte anatómico y comodidad superior desde el primer kilómetro. La mediasuela Dreamstrike+ de amortiguación ligera devuelve energía en cada pisada con precisión técnica, y la suela de caucho con varillas transversales garantiza agarre firme y durabilidad en el asfalto. Fabricada con un 20% de materiales reciclados, rendimiento con responsabilidad.','7,8.5,9,9.5,10','2026-04-23 00:46:54','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(49,'ADIDAS GALAXY 7 CORE BLACK','ID8757','349900.0',2,NULL,NULL,1,'/images/1778111816849-adidas-galaxy-7-core-black.jpg_202605061856.jpeg',0,0,'La Galaxy 7 en negro intenso de Adidas para hombre es la zapatilla de running diario que no necesita presentación. Su parte superior de malla textil resistente ofrece ventilación y sujeción confiables desde el primer kilómetro, en un colorway completamente negro que combina con cualquier atuendo deportivo o casual. La mediasuela Cloudfoam entrega amortiguación suave y reactiva para una pisada cómoda en largas distancias, y la suela de TPU durable proporciona tracción y resistencia al desgaste en cualquier superficie. El compañero de entrenamiento perfecto para el corredor que prefiere que el trabajo hable por él.','7.5,8.5,9,9.5,10.5','2026-04-23 00:49:48','/videos/1779230290787-Tenis_Oakley_HalfTrack_ll_Camo_202605191737__online-video-cutter.com_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(50,'ADIDAS GALAXY 7 GRAY/LILA','JP6591','349900.0',2,NULL,NULL,2,'/images/1778111722832-adidas-galaxy-7-gray_lila.jpg_202605061855.jpeg',0,0,'La Galaxy 7 en gris y lila de Adidas es la zapatilla de running que combina neutralidad y un toque de personalidad en cada zancada. Su parte superior de malla textil resistente ofrece excelente ventilación y sujeción firme, en una paleta de gris con detalles lila que le da un perfil fresco y moderno para hombre y mujer por igual. La mediasuela Cloudfoam proporciona amortiguación suave y eficiente para el running diario, y la suela de TPU garantiza tracción duradera en superficies de asfalto o camino. Un modelo versátil que se lleva con naturalidad a cualquier hora del día.','5.5,6,8.5','2026-04-23 00:52:50','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(51,'OAKLEY MODOC LOW ll BLACK','FOF100245-001','449900.0',3,NULL,NULL,1,'/images/1778111698513-oakley-modoc-low-ll-black.jpg_202605061854.jpeg',1,0,'El Modoc Low II en negro es la zapatilla de aventura urbana más equilibrada de Oakley. Su parte superior combina ante suave con lona perforada estratégicamente para maximizar la transpirabilidad sin comprometer la estructura del calzado. La entresuela de espuma EVA amortigua cada paso de forma eficiente, y la suela de goma vulcanizada con alta resistencia a la tracción y la abrasión garantiza durabilidad en terrenos mixtos. Su silueta baja en negro total proyecta un perfil versátil y discreto que se adapta a cualquier ocasión del día a día.','9.5,10','2026-04-23 03:43:18','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(52,'OAKLEY ANORAK BLACK/RED','FOF100614-009','649900.0',3,NULL,NULL,1,'/images/1778111673938-oakley-anorak-black_red.jpg_202605061854.jpeg',0,0,'La Anorak Low en negro y rojo es la versión más enérgica y atrevida de la línea exterior de Oakley. Su parte superior en gamuza de primera calidad toma un tono negro que se rompe con detalles en rojo vibrante, generando un contraste que comunica actitud en cada paso. La entresuela de espuma EVA proporciona amortiguación ligera y eficaz, mientras la suela de goma robusta ofrece tracción firme en todo tipo de superficies. El emblema de Oakley en metal remata un diseño pensado para quienes quieren que su calzado cuente algo.','7.5,9.5,10','2026-04-23 03:47:51','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(53,'BOTA OAKLEY HALFTRACK MID lll BLACK','FOF100670-001','529900.0',3,NULL,NULL,1,'/images/1778111589483-1776916162385-WhatsApp_Image_2026-04-06_at_15.43.59__1_.jpeg_202605061853.jpeg',0,1,'El Halftrack Mid III en negro es la tercera generación del modelo más icónico de Oakley, renovada con materiales mejorados y un diseño más refinado. Su caña media de materiales sintéticos reforzados y tejido transpirable ofrece soporte estructural en el tobillo con el aspecto táctico y urbano que define a la marca. La entresuela de espuma EVA de nueva generación entrega mayor amortiguación y retorno de energía en cada pisada, y la suela de goma robusta garantiza agarre firme en cualquier superficie. En negro total, una zapatilla que evoluciona sin perder su esencia.','7.5','2026-04-23 03:50:34','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(54,'OAKLEY HALFTRACK ll CAMO COOL GRAY','FOF100469-20A','499900.0',3,NULL,NULL,1,'/images/1778111570083-1776916547521-WhatsApp_Image_2026-04-06_at_14.55.03.jpeg_202605061852.jpeg',0,0,'La Halftrack Low II en camuflaje gris frío es la expresión más táctica y contemporánea del Halftrack de Oakley. Su parte superior en cuero y tejido técnico combina un patrón de camuflaje en tonos grises fríos que evoca la estética militar sin perder coherencia urbana. La entresuela de espuma EVA y la plantilla blanda y perforada ofrecen comodidad activa durante todo el día, mientras la suela de goma de alta tracción garantiza estabilidad en cualquier terreno. Un diseño que no pasa desapercibido y que habla el lenguaje de quienes valoran el detalle.','10,11','2026-04-23 03:56:27','/videos/1779228934233-Tenis_Oakley_HalfTrack_ll_Camo_202605191714__online-video-cutter.com_.mp4','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(55,'ADIDAS RUNFALCON 5 BLACK/WHITE','IH7759','349900.0',2,NULL,NULL,2,'/images/1778111651461-adidas-runfalcon-5-black_white__1_.jpg_202605061854.jpeg',0,0,'La Runfalcon 5 en negro y blanco de Adidas para mujer es la zapatilla de running diario que combina ligereza, comodidad y durabilidad en un solo modelo. Su parte superior de malla resistente y transpirable ofrece sujeción firme y ventilación activa durante cada sesión de entrenamiento o paseo activo. La mediasuela Cloudfoam proporciona amortiguación suave y reactiva que cuida las articulaciones en superficies duras, y la suela Adiwear garantiza tracción firme y resistencia al desgaste a largo plazo. En negro y blanco, una elección clásica y confiable para la mujer que no deja de moverse.','8','2026-04-23 23:25:23','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(56,'ADIDAS RESPONSE RUNNER 2 CORE BLACK/CORE BLACK/GRAY FIVE','KJ1737','299900.0',NULL,NULL,NULL,1,'/images/1778111788550-adidas-response-runner-2-core-black_core-black_gray-five.jpg_202605061856.jpeg',0,0,'La Response Runner 2 en negro intenso con detalles en gris de Adidas es la zapatilla de running que combina un perfil monocromático serio con la tecnología de confort que la marca ofrece. Su parte superior de malla gruesa y transpirable con refuerzos en puntera y talón ofrece sujeción firme y durabilidad en el uso diario intenso. La mediasuela de espuma EVA amortigua cada zancada con eficiencia, y la suela de alta tracción mantiene la estabilidad en cualquier superficie. Un colorway austero y versátil que habla el lenguaje del corredor que va al grano.','7.5,8,8.5,9.5,10.5','2026-04-23 23:28:56','','ORIGINAL',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(57,'ADIZERO EVO SL BLACK/SILVER','JR4888','189900.0',2,NULL,NULL,1,'/images/1778793833503-ChatGPT_Image_14_may_2026__16_24_16.png',0,1,'La Adizero Evo SL en negro y plata de Adidas es la zapatilla de velocidad que lleva la herencia del Adizero Pro Evo 1 al entrenamiento de alta intensidad diario. Su parte superior de malla técnica ultraligera, fabricada con un 20% de materiales reciclados, ofrece ventilación máxima y sujeción estructurada para el pie en movimiento rápido. La mediasuela de espuma LIGHTSTRIKE PRO, la más ligera y reactiva del arsenal de Adidas, devuelve energía en cada pisada con precisión de élite. La suela combina caucho Continental de excelente agarre en el antepié con goma de adherencia superior en el talón. Con apenas 224 gramos, la velocidad nunca fue tan ligera.','7,8,8.5,9.5,10','2026-05-14 21:35:10','','1.1',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(58,'NIKE ZOOMX BLACK/WHITE','CH4318-008','179900.0',1,NULL,NULL,2,'/images/1778856524855-ChatGPT_Image_14_may_2026__17_48_28.png',0,1,'La ZoomX de Nike en negro y blanco es la zapatilla de running de máxima amortiguación de la marca, construida para el corredor que prioriza la comodidad sin sacrificar el rendimiento. Su parte superior de tejido Flyknit flexible y transpirable envuelve el pie con precisión y se adapta a cada movimiento con naturalidad. La mediasuela de espuma ZoomX, el compuesto más reactivo y ligero de Nike, absorbe el impacto de cada pisada y devuelve energía de forma eficiente en superficies duras. La suela de caucho con diseño tipo panal garantiza agarre y durabilidad donde más se necesita. Negro y blanco en una plataforma de amortiguación que redefinió la comodidad en el running moderno.','5.5,6.5,7,8','2026-05-15 15:01:01','','1.1',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(59,'SKECHERS GO RUN RIDE 11 DARK GRAY','SN246079','189900.0',23,NULL,NULL,1,'/images/1779549691781-ChatGPT_Image_23_may_2026__10_22_12.png',0,1,replace('Skechers GO RUN Ride 11\nTenis de running ideales para entrenamientos diarios y largas caminatas. Su diseño ofrece una pisada cómoda, estable y con gran respuesta en cada paso. Incorporan amortiguación Hyper Burst Ice para mayor suavidad y retorno de energía, además de una placa con infusión de carbono que brinda impulso y estabilidad sin perder flexibilidad. Su tecnología Hyper Arc ayuda a una transición más fluida, mientras que la suela Goodyear proporciona excelente agarre y durabilidad en diferentes superficies.\nPerfectos para quienes buscan comodidad, soporte y rendimiento en un solo calzado.','\n',char(10)),'7.5,8,8.5,9.5,10.5','2026-05-23 16:02:42','','1.1',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(60,'SKECHERS GO RUN MAX CUSHION BLACK/GRAY','SN220068','179900.0',23,NULL,NULL,1,'/images/1779726853108-ChatGPT_Image_25_may_2026__11_26_28.png',0,1,replace('Skechers Max Cushioning Premier™ - Perspective\n\nDisfruta una pisada cómoda, ligera y estable con las Skechers Max Cushioning Premier™ - Perspective. Este calzado deportivo cuenta con una parte superior de malla técnica transpirable, cierre de cordones y una entresuela con amortiguación ULTRA GO®, diseñada para brindar mayor suavidad en cada paso.\n\nSu plantilla Air-Cooled Goga Mat™ aporta frescura y confort durante el uso, mientras que la tecnología Natural Rocker Technology® (NRT) ayuda a lograr una transición más fluida desde el talón hasta la punta del pie. Además, su suela flexible con tracción y talón acolchado ofrece mayor estabilidad para caminar, entrenar ligero o usar en el día a día.','\n',char(10)),'7.5,8,8.5,9.5,10.5','2026-05-25 16:36:51','','1.1',NULL);
INSERT INTO "products" ("id","name","model","price","brand_id","category_id","sport_id","gender_id","image","isBestSeller","isNew","description","sizes","createdAt","video","badge","brand") VALUES(61,'NIKE CORTEZ BLUE/WHITE','DZ2795-400','169900.0',1,NULL,NULL,1,'/images/1779749088928-ChatGPT_Image_25_may_2026__17_45_29.png',0,1,replace('Nike Cortez\n\nLas Nike Cortez son un ícono del estilo urbano, reconocidas por su diseño clásico de inspiración retro y su comodidad para el uso diario. Cuentan con una entresuela de espuma ligera que brinda amortiguación suave en cada paso, mientras que su suela de caucho con patrón tipo espiguilla ofrece buen agarre y durabilidad.\n\nSu estructura combina materiales resistentes, ajuste cómodo y una punta ligeramente más amplia para mayor confort. Gracias a su diseño atemporal, son ideales para quienes buscan un calzado casual, versátil y fácil de combinar en cualquier ocasión.','\n',char(10)),'7,8,8.5,9.5,10','2026-05-25 22:40:01','','1.1',NULL);
